package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.ApplicationSessionIdentity;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;

/** Human orchestration only. Queuing is not launch, adoption is not confirmation. */
public final class TaskPlanDraftService {
    private final EnterpriseAccess access;private final TaskService tasks;private final TaskPlanService plans;private final ResourceReadAuthority resources;
    private final TaskPlanDraftSchema schema;private final PermissionSchema json;private final TaskPlanDraftAdmission admission;private final TaskPlanDraftJobs jobs;
    private final AgentPublicationAuthority publications;private final AgentExecutionPolicyAuthority policies;private final TaskPlanDraftPackagePreflight packages;
    private final TaskPlanDraftSavedCandidate candidates;private final TaskPlanDraftHumanCheck checks;private final TaskPlanDraftSavedToolReceipt tools;
    private final JdbcTemplate db;private final SchemaCatalogue shared;
    public TaskPlanDraftService(DataSource data,EnterpriseAccess access,TaskService tasks,TaskPlanService plans,ResourceReadAuthority resources,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftAdmission admission,TaskPlanDraftJobs jobs,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,TaskPlanDraftPackagePreflight packages,TaskPlanDraftSavedCandidate candidates,TaskPlanDraftHumanCheck checks,TaskPlanDraftSavedToolReceipt tools)throws Exception {
        db=new JdbcTemplate(data);db.setQueryTimeout(5);this.access=access;this.tasks=tasks;this.plans=plans;this.resources=resources;this.schema=schema;this.json=json;this.admission=admission;this.jobs=jobs;this.publications=publications;this.policies=policies;this.packages=packages;this.candidates=candidates;this.checks=checks;this.tools=tools;shared=SchemaCatalogue.fromClasspath();
    }
    public record Reply(JsonNode envelope,int status){}
    Reply start(ApplicationSessionIdentity.Verified subject,String context,String project,String task,String key,byte[] bytes)throws Exception {
        json.headers(context,key);ids(project,task);var request=schema.start(bytes);String hash=schema.hash(schema.read(request.canonical()));
        var prior=access.execute(subject,a->ThrowingSupplier.of(()->{var fixed=current(a,context,project,task);maintain(a,project,task);runGrant(a,fixed);return replay(a,task,"TASK-PLAN-DRAFT",key,hash,null);}).get());if(prior!=null)return prior;
        var publication=publications.prepare(subject,context,request.request().agentReleaseId(),TaskPlanDraftAdmission.PURPOSE,false);
        var selection=access.execute(subject,a->ThrowingSupplier.of(()->packages.select(admit(a,context,project,task,request,publication))).get());
        var physical=packages.readHuman(subject,selection);
        return access.execute(subject,a->ThrowingSupplier.of(()->{
            var current=admit(a,context,project,task,request,publication);var replay=replay(a,task,"TASK-PLAN-DRAFT",key,hash,null);if(replay!=null)return replay;
            var missing=admission.missingPackageSelections(current,physical);if(!missing.isEmpty()){
                var data=json.object().put("schema_version","1.0.0").put("tenant_id",a.context().tenant_id()).put("project_id",project).put("task_id",task).put("task_revision",current.fixedTask().head().taskRevision()).put("status","PREPARATION_REQUIRED");data.set("missing_requirements",missing);schema.validate("Preparation",data);return envelope(data,409,current.fixedTask().head().revision().toString());
            }
            var ready=admission.withPackages(current,physical);String operation=begin(a,task,"TASK-PLAN-DRAFT",key,hash,ready.classification());
            var job=jobs.queued(ready,operation,key);ready.requireUnchanged();var result=envelope(view(job,null,null,null),202,current.fixedTask().head().revision().toString());complete(a,operation,result);return result;
        }).get());
    }
    private TaskPlanDraftAdmission.Verified admit(EnterpriseAccess.Admission a,String context,String project,String task,TaskPlanDraftSchema.Original request,AgentPublicationAuthority.PreparedPublication publication)throws Exception {
        var published=publications.require(a,request.request().agentReleaseId(),TaskPlanDraftAdmission.PURPOSE,publication);var pin=request.request().executionPolicy();var policy=policies.requireByVersion(a,pin.version_id(),pin.content_sha256(),project,TaskPlanDraftAdmission.PURPOSE);return admission.require(a,context,project,task,request,published,policy);
    }
    Reply read(ApplicationSessionIdentity.Verified subject,String context,String project,String task,String run)throws Exception {
        ids(project,task,run);var present=access.execute(subject,a->ThrowingSupplier.of(()->{current(a,context,project,task);var job=job(a,project,task,run);return !db.queryForList("SELECT artifact_id FROM task_plan_draft_candidate WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenant(),run).isEmpty();}).get());
        if(!present)return access.execute(subject,a->ThrowingSupplier.of(()->{var fixed=current(a,context,project,task);return envelope(view(job(a,project,task,run),null,null,null),200,fixed.head().revision().toString());}).get());
        var saved=candidates.read(subject,context,project,task,run);return access.execute(subject,a->ThrowingSupplier.of(()->{var actual=saved.require(a);var check=checks.candidate(actual);JsonNode tool=null;if(hasTool(actual.job()))tool=tools.require(actual).receipt();check.requireUnchanged();return envelope(view(actual.job(),actual,check.receipt(),tool),200,actual.human().fixedTask().head().revision().toString());}).get());
    }
    Reply adopt(ApplicationSessionIdentity.Verified subject,String context,String project,String task,String run,String key,byte[] bytes)throws Exception {
        json.headers(context,key);ids(project,task,run);var request=schema.validate("Adopt",schema.read(TaskPlanDraftSchema.utf8(bytes)));String hash=schema.hash(Map.of("project_id",project,"task_id",task,"run_id",run,"request",request));
        var prior=access.execute(subject,a->ThrowingSupplier.of(()->{current(a,context,project,task);maintain(a,project,task);return replay(a,task,"TASK-PLAN-DRAFT-ADOPT",key,hash,run);}).get());if(prior!=null)return prior;
        var read=candidates.read(subject,context,project,task,run);
        return access.execute(subject,a->ThrowingSupplier.of(()->{
            current(a,context,project,task);maintain(a,project,task);var replay=replay(a,task,"TASK-PLAN-DRAFT-ADOPT",key,hash,run);if(replay!=null)return replay;
            var saved=read.require(a);var originalTool=tools.require(saved);if(!saved.receiptSha256().equals(request.required("candidate_receipt_sha256").asText()))conflict();
            var fresh=checks.candidate(saved);requireAcknowledgedCheck(saved,request.required("check_receipt_sha256").asText(),fresh.receipt());
            var j=saved.job();String operation=begin(a,task,"TASK-PLAN-DRAFT-ADOPT",key,hash,j.classification());
            var input=json.object().put("schema_version","1.0.0").put("expected_revision",request.required("expected_revision").asText()).put("schema_ref",shared.schemaRef("artifacts","PlanCandidate")).put("reason",request.required("reason").asText());input.set("base_version",request.required("base_plan_revision"));input.set("content",saved.candidate());
            fresh.requireUnchanged();originalTool.requireUnchanged();
            var result=plans.saveWithin(a,context,internalKey(key,run),task,schema.canonical(input).getBytes(StandardCharsets.UTF_8));
            // TK03 legitimately advanced the head. Reacquire the same human's current proof, never reuse the stale head proof.
            var after=read.require(a);var fixed=tasks.fixedTask(a,task);var draft=plans.readFixed(a,fixed,result.planRevision(),true);
            if(!"DRAFT".equals(draft.status())||!schema.hash(after.candidate()).equals(draft.contentSha256()))bad();
            var origin=origin(a,after,fresh.receiptSha256(),operation,draft,request,hash,bytes);
            var response=new Reply(result.envelope(),result.httpStatus());complete(a,operation,response);verifyOrigin(a,origin,result.planRevision(),run);return response;
        }).get());
    }
    private void requireAcknowledgedCheck(TaskPlanDraftSavedCandidate.Verified saved,String hash,JsonNode fresh)throws Exception {
        var j=saved.job();var row=one(db.queryForList("SELECT * FROM task_plan_draft_check WHERE tenant_id=? AND run_id=? AND receipt_sha256=? LIMIT 2",j.tenant(),j.run(),hash));var old=schema.validate("CheckReceipt",schema.read(text(row,"receipt_json")));
        if(!hash.equals(schema.hash(old))||!saved.human().admission().actorId().equals(old.required("actor_id").asText()))conflict();
        for(String field:List.of("tenant_id","project_id","task_id","task_revision","run_id","candidate_receipt_sha256","candidate_sha256","target_kind","target_revision","target_sha256","source_scope_sha256","authority_sha256","coverage_sha256","result","missing_item_ids","template","profile"))if(!old.required(field).equals(fresh.required(field)))conflict();
        var audit=one(db.queryForList("SELECT resource_ref,action,result,subject_id FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2",j.tenant(),row.get("audit_id")));var event=one(db.queryForList("SELECT payload,event_type,aggregate_id FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2",j.tenant(),row.get("event_id")));
        if(!old.equals(schema.read(text(audit,"resource_ref")))||!"task.plan_draft.human_check".equals(audit.get("action"))||!"SUCCESS".equals(audit.get("result"))||!old.required("actor_id").asText().equals(audit.get("subject_id"))||!old.equals(schema.read(text(event,"payload")))||!"task.plan_draft.human_check".equals(event.get("event_type"))||!j.run().equals(event.get("aggregate_id")))bad();
    }
    private JsonNode origin(EnterpriseAccess.Admission a,TaskPlanDraftSavedCandidate.Verified saved,String checked,String operation,TaskPlanWriteProtocol.View draft,JsonNode request,String requestHash,byte[] raw)throws Exception {
        var j=saved.job();var at=now();String audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var receipt=json.object().put("schema_version","1.0.0").put("tenant_id",j.tenant()).put("project_id",j.project()).put("task_id",j.task()).put("task_revision",j.taskRevision()).put("run_id",j.run()).put("actor_id",a.actorId()).put("operation_id",operation).put("candidate_artifact_id",saved.artifactId()).put("candidate_sha256",schema.hash(saved.candidate())).put("candidate_receipt_sha256",saved.receiptSha256()).put("check_receipt_sha256",checked).put("draft_revision",draft.planRevision()).put("draft_sha256",draft.contentSha256()).putNull("parent_draft_revision").put("created_at",at.toInstant(ZoneOffset.UTC).toString());schema.validate("Origin",receipt);
        var witness=json.object();witness.set("receipt",receipt);witness.set("original_request",request);witness.put("original_body",new String(raw,StandardCharsets.UTF_8)).put("original_body_sha256",WireValues.sha256(raw)).put("request_sha256",requestHash);
        // Origin locator consumes receipt-only journal; original request is separately retained in the operation journal.
        journal(a,j,audit,event,"task.plan_draft.adopted",draft.planRevision(),receipt,at);
        String originalAudit=UUID.randomUUID().toString(),originalEvent=UUID.randomUUID().toString();journal(a,j,originalAudit,originalEvent,"task.plan_draft.adoption.request",operation,witness,at);
        var row=meta(a,j,at);row.putAll(Map.of("task_id",j.task(),"run_id",j.run(),"draft_revision",draft.planRevision(),"draft_sha256",draft.contentSha256(),"candidate_receipt_sha256",saved.receiptSha256(),"check_receipt_sha256",checked,"operation_id",operation,"receipt_json",schema.canonical(receipt),"receipt_sha256",schema.hash(receipt)));row.put("parent_draft_revision",null);row.put("audit_id",audit);row.put("event_id",event);insert("task_plan_draft_origin",row);return receipt;
    }
    private TaskService.VerifiedTask current(EnterpriseAccess.Admission a,String context,String project,String task)throws Exception {TaskPlanDraftAdmission.current(a,context);if(a.planDraftWorker()||a.formalWorker()||a.controlWorker())deny();var fixed=tasks.fixedTask(a,task);if(!project.equals(fixed.head().projectId()))deny();return fixed;}
    private void maintain(EnterpriseAccess.Admission a,String project,String task)throws Exception {resources.require(a,new PermissionProtocol.Scope(a.context().tenant_id(),project,"TASK",task),"plan.write","PLAN_MAINTENANCE");}
    private void runGrant(EnterpriseAccess.Admission a,TaskService.VerifiedTask task)throws Exception {resources.require(a,new PermissionProtocol.Scope(a.context().tenant_id(),task.head().projectId(),"TASK",task.head().taskId()),"task.run","TASK_EXECUTION");}
    private TaskPlanDraftJobs.Job job(EnterpriseAccess.Admission a,String project,String task,String run)throws Exception {var j=jobs.byRun(a.context().tenant_id(),run);if(!project.equals(j.project())||!task.equals(j.task()))deny();return j;}
    private JsonNode view(TaskPlanDraftJobs.Job j,TaskPlanDraftSavedCandidate.Verified candidate,JsonNode check,JsonNode tool)throws Exception {
        String status=one(db.query("SELECT status FROM system_job_run WHERE tenant_id=? AND run_id=? AND job_type='PLAN_DRAFT' AND execution_kind='SYSTEM_JOB' LIMIT 2",(r,n)->r.getString(1),j.tenant(),j.run()));var n=json.object().put("schema_version","1.0.0").put("tenant_id",j.tenant()).put("project_id",j.project()).put("task_id",j.task()).put("task_revision",j.taskRevision()).put("run_id",j.run()).put("status",status).put("input_sha256",j.inputHash());
        if(candidate==null){n.putNull("candidate_artifact_id");n.putNull("candidate_receipt_sha256");n.putNull("candidate");}else{n.put("candidate_artifact_id",candidate.artifactId()).put("candidate_receipt_sha256",candidate.receiptSha256());n.set("candidate",candidate.candidate());shared.validate("artifacts",candidate.candidate(),"PlanCandidate");}if(check==null)n.putNull("check_receipt_sha256");else n.put("check_receipt_sha256",schema.hash(check));n.set("check_receipt",check==null?json.object().nullNode():check);n.set("tool_receipt",tool==null?json.object().nullNode():tool);return schema.validate("View",n);
    }
    private boolean hasTool(TaskPlanDraftJobs.Job j){return !db.queryForList("SELECT receipt_sha256 FROM task_plan_draft_tool_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",j.tenant(),j.run()).isEmpty();}
    private Reply replay(EnterpriseAccess.Admission a,String task,String name,String key,String hash,String run)throws Exception {
        var rows=db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND subject_id=? AND operation_name=? AND idempotency_key=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),a.actorId(),name,key);if(rows.isEmpty())return null;var row=one(rows);
        if(!hash.equals(row.get("request_sha256"))||!task.equals(row.get("target_id")))conflict();if(!"COMPLETED".equals(row.get("state"))||row.get("http_status")==null||row.get("response_ref")==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
        if(!schema.manifest().equals(row.get("schema_manifest_sha256"))||!"1.0.0".equals(row.get("schema_version")))bad();var response=schema.read(text(row,"response_ref"));shared.validate("interfaces",response,"Envelope");
        if(run==null){var data=schema.validate("View",response.required("data"));var original=job(a,data.required("project_id").asText(),task,data.required("run_id").asText());if(!text(row,"operation_id").equals(original.operation())||!hash.equals(original.requestHash())||!original.inputHash().equals(data.required("input_sha256").asText())||!original.taskRevision().equals(data.required("task_revision").asText())||!original.tenant().equals(data.required("tenant_id").asText())||!"QUEUED".equals(data.required("status").asText())||!data.required("candidate").isNull()||!data.required("check_receipt").isNull()||!data.required("tool_receipt").isNull())bad();}
        else {shared.validate("task-plan-view",response.required("data"),"View");String draft=response.required("data").required("plan_revision").asText();var origin=one(db.queryForList("SELECT receipt_json FROM task_plan_draft_origin WHERE tenant_id=? AND draft_revision=? AND operation_id=? AND run_id=? AND task_id=? LIMIT 2",a.context().tenant_id(),draft,row.get("operation_id"),run,task));var originalOrigin=schema.validate("Origin",schema.read(text(origin,"receipt_json")));verifyOrigin(a,originalOrigin,draft,run);verifyAdoptionRequest(a,text(row,"operation_id"),originalOrigin,hash);var fixed=tasks.fixedTask(a,task);var original=plans.readFixed(a,fixed,draft,false);if(!original.contentSha256().equals(response.required("data").required("content_sha256").asText())||!json.tree(original.content()).equals(response.required("data").required("content")))bad();}
        return new Reply(response,((Number)row.get("http_status")).intValue());
    }
    private void verifyAdoptionRequest(EnterpriseAccess.Admission a,String operation,JsonNode origin,String hash)throws Exception {
        var rows=db.queryForList("SELECT resource_ref,subject_id,result,created_by FROM audit_event WHERE tenant_id=? AND request_id=? AND action='task.plan_draft.adoption.request' LIMIT 2",a.context().tenant_id(),operation);var audit=one(rows);var witness=schema.read(text(audit,"resource_ref"));
        if(!a.actorId().equals(audit.get("subject_id"))||!a.actorId().equals(audit.get("created_by"))||!"SUCCESS".equals(audit.get("result"))||!origin.equals(witness.required("receipt"))||!hash.equals(witness.required("request_sha256").asText()))bad();
        byte[] original=witness.required("original_body").asText().getBytes(StandardCharsets.UTF_8);if(!WireValues.sha256(original).equals(witness.required("original_body_sha256").asText())||!schema.validate("Adopt",schema.read(TaskPlanDraftSchema.utf8(original))).equals(witness.required("original_request")))bad();
        if(!hash.equals(schema.hash(Map.of("project_id",origin.required("project_id").asText(),"task_id",origin.required("task_id").asText(),"run_id",origin.required("run_id").asText(),"request",witness.required("original_request")))))bad();
        var events=db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND event_type='task.plan_draft.adoption.request' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.receipt.operation_id'))=? LIMIT 2",(r,n)->r.getString(1),a.context().tenant_id(),origin.required("run_id").asText(),operation);if(!witness.equals(schema.read(one(events))))bad();
    }
    private void verifyOrigin(EnterpriseAccess.Admission a,JsonNode receipt,String draft,String run)throws Exception {
        var row=one(db.queryForList("SELECT * FROM task_plan_draft_origin WHERE tenant_id=? AND draft_revision=? AND run_id=? LIMIT 2",a.context().tenant_id(),draft,run));if(!receipt.equals(schema.read(text(row,"receipt_json")))||!schema.hash(receipt).equals(row.get("receipt_sha256"))||!receipt.required("actor_id").asText().equals(row.get("created_by")))bad();
        var audit=one(db.queryForList("SELECT resource_ref,action,result FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2",a.context().tenant_id(),row.get("audit_id")));var event=one(db.queryForList("SELECT payload,event_type FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2",a.context().tenant_id(),row.get("event_id")));if(!receipt.equals(schema.read(text(audit,"resource_ref")))||!"task.plan_draft.adopted".equals(audit.get("action"))||!"SUCCESS".equals(audit.get("result"))||!receipt.equals(schema.read(text(event,"payload")))||!"task.plan_draft.adopted".equals(event.get("event_type")))bad();
    }
    private String begin(EnterpriseAccess.Admission a,String task,String name,String key,String hash,String classification){String id=UUID.randomUUID().toString();var at=now();changed(db.update("INSERT INTO operation_record(tenant_id,operation_id,subject_id,operation_name,idempotency_key,request_sha256,state,target_id,schema_version,schema_manifest_sha256,created_by,created_at,classification,revision,updated_at) VALUES(?,?,?,?,?,?,'PROCESSING',?,'1.0.0',?,?,?,?,1,?)",a.context().tenant_id(),id,a.actorId(),name,key,hash,task,schema.manifest(),a.actorId(),at,classification,at));return id;}
    private void complete(EnterpriseAccess.Admission a,String operation,Reply response)throws Exception {changed(db.update("UPDATE operation_record SET state='COMPLETED',http_status=?,response_ref=?,revision=2,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND operation_id=? AND subject_id=? AND state='PROCESSING' AND revision=1",response.status(),schema.canonical(response.envelope()),a.context().tenant_id(),operation,a.actorId()));}
    private Reply envelope(JsonNode data,int status,String revision)throws Exception {var e=json.tree(new InterfaceProtocol.Envelope("1.0.0",UUID.randomUUID().toString(),revision,data));shared.validate("interfaces",e,"Envelope");return new Reply(e,status);}
    private void journal(EnterpriseAccess.Admission a,TaskPlanDraftJobs.Job j,String audit,String event,String action,String request,JsonNode value,LocalDateTime at)throws Exception {var row=meta(a,j,at);row.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action",action,"resource_ref",schema.canonical(value),"result","SUCCESS","request_id",request,"trace_id",j.run()));insert("audit_event",row);insert("outbox_event",Map.of("tenant_id",j.tenant(),"event_id",event,"aggregate_id","task.plan_draft.adopted".equals(action)?j.task():j.run(),"aggregate_revision",1,"event_type",action,"payload",schema.canonical(value),"occurred_at",at));}
    private Map<String,Object> meta(EnterpriseAccess.Admission a,TaskPlanDraftJobs.Job j,LocalDateTime at){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("project_id",j.project());m.put("created_by",a.actorId());m.put("created_at",at);m.put("classification",j.classification());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schema.manifest());return m;}
    private void insert(String table,Map<String,Object> m){var keys=new ArrayList<>(m.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(m::get).toArray()));}
    private LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}private static String internalKey(String key,String run)throws java.security.NoSuchAlgorithmException{return "n01-adopt-"+WireValues.sha256((run+"/"+key).getBytes(StandardCharsets.UTF_8));}private static void ids(String... ids){for(String id:ids)WireValues.uuid(id);}private static String text(Map<String,Object> row,String key){return Objects.requireNonNull(row.get(key)).toString();}private static <T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)bad();return rows.get(0);}private static void changed(int count){if(count!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void conflict(){throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
